sys_script.script:
(function executeRule(current, previous) {
    // 1. Reset tracking
    current.u_last_submitted_on = new GlideDateTime();
    current.u_resubmission_count = (parseInt(current.u_resubmission_count) || 0) + 1;
    current.approved_limit = 0;

    // 2. WIPE ALL APPROVER FIELDS (The clean slate)
    var approverFields = [
        'u_approver_tsh', 'u_approver_rhm', 'u_approver_zhm', 'u_approver_zch', 'u_approver_ho',
        'u_approver_nsh', 'u_approver_nsh_cch', 'u_approver_cmo', 'u_approver_cmo_cfo', 'u_approver_md',
        'u_approver_tsm', 'u_approver_rh_ch_rmc', 'u_approver_zh_rmc', 'u_approver_head_rmc', 
        'u_approver_head_key_ch_rmc', 'u_approver_head_key_cch', 'u_approver_bh', 'u_approver_bh_cfo',
        'u_approver_tsh_bpd', 'u_approver_zh_bpd', 'u_approver_hsbpd', 'u_approver_hbpd', 
        'u_approver_cch_hbpd', 'u_approver_cfo', 'u_approver'
    ];
    for (var f = 0; f < approverFields.length; f++) {
        current.setValue(approverFields[f], ''); 
    }

    // 3. Cleanup old approvals/flow
    var apprGr = new GlideRecord('sysapproval_approver');
    var qc = apprGr.addQuery('document_id', current.sys_id);
    qc.addOrCondition('sysapproval', current.sys_id);
    apprGr.addQuery('state', 'requested'); 
    apprGr.query();
    while (apprGr.next()) {
        apprGr.state = 'cancelled';
        apprGr.update();
    }

    // ... (Keep your existing Flow Designer cancellation code here) ...
})(current, previous);
